const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Sumatra and Borneo regions
  var sumatra = ee.Geometry.Polygon([
    [[95.0, -6.0], [106.0, -6.0], [106.0, 6.0], [95.0, 6.0], [95.0, -6.0]]
  ]);

  var borneo = ee.Geometry.Polygon([
    [[108.0, -5.0], [119.0, -5.0], [119.0, 7.0], [108.0, 7.0], [108.0, -5.0]]
  ]);

  var region = ee.Geometry.MultiPolygon([sumatra, borneo]);

  // Get MODIS Active Fire data
  var fires2022 = ee.ImageCollection('MODIS/006/1/MCD14DL')
    .filterDate('2022-01-01', '2023-01-01')
    .filterBounds(region);

  var fires2023 = ee.ImageCollection('MODIS/006/1/MCD14DL')
    .filterDate('2023-01-01', '2024-01-01')
    .filterBounds(region);

  // Check collection sizes
  var count2022 = fires2022.size().getInfo();
  var count2023 = fires2023.size().getInfo();

  console.log(`2022 Fire Images: ${count2022}`);
  console.log(`2023 Fire Images: ${count2023}`);

  if (count2022 === 0 || count2023 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Count fire detections (each pixel with confidence > 0)
  var countFires2022 = fires2022.select('Confidence')
    .map(function(img) {
      return img.gt(0).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
    })
    .aggregate_array('Confidence')
    .reduce(ee.Reducer.sum())
    .getInfo();

  var countFires2023 = fires2023.select('Confidence')
    .map(function(img) {
      return img.gt(0).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
    })
    .aggregate_array('Confidence')
    .reduce(ee.Reducer.sum())
    .getInfo();

  console.log(`2022 Fire Detections: ${countFires2022}`);
  console.log(`2023 Fire Detections: ${countFires2023}`);

  // Validate results
  if (countFires2022 === null || countFires2023 === null || 
      isNaN(countFires2022) || isNaN(countFires2023)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine answer
  if (countFires2023 > countFires2022) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
